package org.jarvisassistant.app;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.*;
import android.webkit.CookieManager;
import android.widget.*;
import com.google.android.gms.tasks.Tasks;
import com.google.android.gms.wearable.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Live pairing surface. Legacy activity remains available for old notifications. */
public final class WatchConnectionsActivity extends Activity {
    private String origin;private TextView title,status,detail,connection;private Button pair,enable,retry,disconnect;private ConnectionScene scene;private ProgressBar progress;private CancellationSignal biometric;
    private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile ApiClient active;private boolean visible,busy;private int epoch;
    private android.content.SharedPreferences prefs(){return getSharedPreferences("WatchLink",MODE_PRIVATE);}
    private int dp(int value){return NativeStyle.dp(this,value);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);try{origin=EndpointPolicy.connection(getIntent().getStringExtra("origin"));}catch(Exception error){finish();return;}
        LinearLayout root=NativeStyle.surface(this);root.addView(NativeStyle.toolbar(this,"Your watch","Pair once. Reach JARVIS from your wrist.",this::finish));ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout body=NativeStyle.column(this);body.setPadding(dp(24),0,dp(24),dp(28));scroll.addView(body);
        scene=new ConnectionScene(this,"Watch");body.addView(scene,new LinearLayout.LayoutParams(-1,dp(116)));LinearLayout connectionCard=NativeStyle.card(this);body.addView(connectionCard,new LinearLayout.LayoutParams(-1,-2));LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);title=NativeStyle.title(this,"Galaxy Watch",24);heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));progress=new ProgressBar(this);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(NativeStyle.ACCENT));heading.addView(progress,new LinearLayout.LayoutParams(dp(20),dp(20)));connectionCard.addView(heading);
        NativeStyle.gap(connectionCard,12);status=NativeStyle.text(this,"Finding your watch…",15,NativeStyle.ACCENT);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);connectionCard.addView(status);NativeStyle.gap(connectionCard,14);detail=NativeStyle.text(this,"Open JARVIS on your unlocked watch.",14,NativeStyle.MUTED);connectionCard.addView(detail);NativeStyle.gap(body,20);
        pair=NativeStyle.action(this,"Pair watch","connection",true,this::pair);body.addView(pair);NativeStyle.gap(body,10);enable=NativeStyle.action(this,"Connect watch","connection",true,this::start);body.addView(enable);enable.setVisibility(View.GONE);NativeStyle.gap(body,10);retry=NativeStyle.action(this,"Try again","refresh",false,this::inspect);body.addView(retry);retry.setVisibility(View.GONE);NativeStyle.gap(body,24);
        LinearLayout abilities=NativeStyle.card(this);body.addView(abilities);abilities.addView(NativeStyle.title(this,"Ready from your wrist",17));NativeStyle.gap(abilities,12);abilities.addView(NativeStyle.text(this,"Voice · Files · Codex\nMedia, mouse & keyboard",14,NativeStyle.TEXT));NativeStyle.gap(abilities,12);abilities.addView(NativeStyle.text(this,"Wake listening stays off until you start it.",12,NativeStyle.MUTED));NativeStyle.gap(abilities,12);abilities.addView(NativeStyle.action(this,"How watch access works","shield",false,()->new AlertDialog.Builder(this).setTitle("Pair once, then use your watch").setMessage("One fingerprint on this phone trusts the exact watch key for files, coding sessions and laptop input. Controls work while the watch is unlocked, until you disconnect it.\n\nWindows sign-in keeps its separate phone approval. The enabled phone connection can restart after updates or reboot. No microphone starts automatically.").setPositiveButton("Got it",null).show()));NativeStyle.gap(body,20);connection=NativeStyle.text(this,"Connection status updates automatically.",12,NativeStyle.MUTED);body.addView(connection);NativeStyle.gap(body,18);disconnect=NativeStyle.action(this,"Disconnect watch",null,false,()->new AlertDialog.Builder(this).setTitle("Disconnect watch?").setMessage("Remove its saved laptop access and stop the phone connection. Your phone's laptop pairing stays saved.").setNegativeButton("Keep paired",null).setPositiveButton("Disconnect",(d,w)->revoke()).show());body.addView(disconnect);disconnect.setVisibility(View.GONE);NativeStyle.reveal(body);
    }
    private void inspect(){if(!visible||busy)return;busy=true;int generation=epoch;progress.setVisibility(View.VISIBLE);scene.state(false,true);worker.execute(()->{
        boolean linked=!prefs().getString("approvedId","").isEmpty()&&prefs().getString("approvedId","").equals(prefs().getString("watchId","")),present=false,online=false,wearable=true;String name=prefs().getString("name","Galaxy Watch"),node=prefs().getString("node","");
        try{List<Node> nodes=Tasks.await(Wearable.getNodeClient(this).getConnectedNodes(),8,TimeUnit.SECONDS);for(Node item:nodes)if(item.getId().equals(node))present=true;if(present)Wearable.getMessageClient(this).sendMessage(node,"/jarvis/watch/v2/key-request",new byte[0]);}catch(Exception error){wearable=false;}
        try(ApiClient client=new ApiClient(origin,CookieManager.getInstance().getCookie(origin),8000)){active=client;client.json("/api/health",null);online=true;if(linked)try{JSONArray list=client.json("/api/watch/status",null).getJSONArray("watches");boolean found=false;for(int i=0;i<list.length();i++)if(list.getJSONObject(i).getString("id").equals(prefs().getString("approvedId","")))found=true;if(!found){linked=false;prefs().edit().remove("approvedId").apply();}}catch(ApiClient.Failure ignored){}}catch(Exception ignored){}finally{active=null;}
        String message=linked?(present?online?WatchBridgeService.current!=null?"Ready on your wrist":"Paired · ready to connect":"Laptop offline":"Watch offline"):"Ready to pair";
        String note=!wearable?"Open Galaxy Wearable to check your watch connection.":linked&&!present?"Reconnect in Galaxy Wearable. Your pairing stays saved.":!online?"Check Tailscale and make sure the laptop is awake.":!linked?"Open JARVIS on your unlocked watch, then tap Pair watch. Approve once on this phone.":"Open JARVIS on the watch. Your features are ready through this phone.";
        final boolean paired=linked,connected=present,host=online;final String next=message,help=note,label=name;main.post(()->{if(!visible||generation!=epoch)return;busy=false;progress.setVisibility(View.INVISIBLE);scene.state(connected,false);title.setText(label);NativeStyle.status(status,next,false);status.setTextColor(connected&&host?NativeStyle.ACCENT:NativeStyle.WARNING);NativeStyle.status(detail,help,false);pair.setVisibility(paired?View.GONE:View.VISIBLE);enable.setVisibility(paired&&WatchBridgeService.current==null?View.VISIBLE:View.GONE);retry.setVisibility(host&&connected?View.GONE:View.VISIBLE);disconnect.setVisibility(paired?View.VISIBLE:View.GONE);connection.setText((connected?"Watch ↔ phone connected":"Watch not connected")+"\n"+(host?"Laptop reachable":"Laptop not reachable · checking automatically"));});
    });}
    private void pair(){if(busy)return;Wearable.getNodeClient(this).getConnectedNodes().addOnSuccessListener(this,nodes->{if(nodes.isEmpty()){status.setText("Connect the watch in Galaxy Wearable first.");return;}if(nodes.size()==1)choose(nodes.get(0));else{String[] names=new String[nodes.size()];for(int i=0;i<names.length;i++)names[i]=nodes.get(i).getDisplayName();new AlertDialog.Builder(this).setTitle("Choose your watch").setItems(names,(d,i)->choose(nodes.get(i))).show();}});}
    private void choose(Node node){if(!prefs().getString("node","").equals(node.getId()))prefs().edit().remove("publicKey").remove("watchId").remove("approvedId").apply();prefs().edit().putString("node",node.getId()).putString("name",node.getDisplayName()).putString("origin",origin).apply();Wearable.getMessageClient(this).sendMessage(node.getId(),"/jarvis/watch/v2/key-request",new byte[0]);busy=true;pair.setEnabled(false);progress.setVisibility(View.VISIBLE);status.setText("Waiting for the watch's secure key…");int generation=epoch;
        worker.execute(()->{try{long until=SystemClock.elapsedRealtime()+7000;while(prefs().getString("publicKey","").isEmpty()&&SystemClock.elapsedRealtime()<until&&visible&&generation==epoch)Thread.sleep(150);String key=prefs().getString("publicKey",""),watch=prefs().getString("watchId","");if(key.isEmpty())throw new java.io.IOException("Open JARVIS on your unlocked watch. Set a watch screen lock if prompted, then pair again.");
            try(ApiClient client=new ApiClient(origin,CookieManager.getInstance().getCookie(origin))){active=client;JSONObject challenge=client.json("/api/watch/prepare",new JSONObject().put("phoneId",RemoteSigner.deviceId()).put("node",node.getId()).put("name",node.getDisplayName()).put("publicKey",key));CountDownLatch done=new CountDownLatch(1);String[] proof={null};main.post(()->{if(!visible||generation!=epoch){done.countDown();return;}biometric=WatchPairSigner.approve(this,challenge.optString("payload"),challenge.optString("computerId"),watch,node.getId(),new RemoteSigner.Result(){public void approved(String value){proof[0]=value;done.countDown();}public void failed(){done.countDown();}});});if(!done.await(60,TimeUnit.SECONDS)||proof[0]==null||!visible||generation!=epoch)throw new java.io.IOException("Pairing was not approved. Your phone pairing is unchanged.");JSONObject result=client.json("/api/watch/approve",new JSONObject().put("requestId",challenge.getString("requestId")).put("signature",proof[0]));if(!result.optBoolean("paired")||!watch.equals(result.optString("watchId")))throw new java.io.IOException("Pairing could not be confirmed.");prefs().edit().putString("approvedId",watch).apply();main.post(()->{if(visible&&generation==epoch){busy=false;pair.setEnabled(true);start();}});}
        }catch(Exception error){main.post(()->{if(visible&&generation==epoch){busy=false;pair.setEnabled(true);progress.setVisibility(View.INVISIBLE);status.setText(error instanceof java.io.IOException?error.getMessage():"Unlock the primary JARVIS workspace and pair this phone with Windows first.");retry.setVisibility(View.VISIBLE);}});}finally{active=null;}});
    }
    private void start(){if(prefs().getString("approvedId","").isEmpty()){pair();return;}if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT},84);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},84);return;}try{prefs().edit().putBoolean("connectionEnabled",true).apply();startForegroundService(new Intent(this,WatchBridgeService.class));main.postDelayed(this::inspect,400);}catch(RuntimeException error){status.setText("Reopen this screen to connect the watch.");}}
    private void revoke(){if(busy)return;prefs().edit().putBoolean("connectionEnabled",false).apply();stopService(new Intent(this,WatchBridgeService.class));busy=true;int generation=epoch;worker.execute(()->{try(ApiClient client=new ApiClient(origin,CookieManager.getInstance().getCookie(origin))){active=client;client.json("/api/watch/revoke",new JSONObject().put("watchId",prefs().getString("approvedId","")));prefs().edit().clear().apply();main.post(()->{if(visible&&generation==epoch){busy=false;inspect();}});}catch(Exception error){main.post(()->{if(visible&&generation==epoch){busy=false;status.setText("Connection stopped. Reconnect to the laptop and unlock JARVIS to finish removing watch trust.");}});}finally{active=null;}});}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==84&&results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)start();else status.setText("Allow nearby devices and notifications to keep the watch connected.");}
    private final Runnable poll=new Runnable(){public void run(){if(visible){inspect();main.postDelayed(this,4000);}}};
    @Override protected void onResume(){super.onResume();visible=true;busy=false;main.removeCallbacks(poll);poll.run();}
    @Override protected void onPause(){visible=false;epoch++;main.removeCallbacks(poll);if(biometric!=null)biometric.cancel();ApiClient client=active;if(client!=null)client.close();busy=false;super.onPause();}
    @Override protected void onDestroy(){worker.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
}
